    for start, end, title, items in first:
        title_cell = table.cell(1, start).merge(table.cell(1, end))
        body_cell = table.cell(2, start).merge(table.cell(2, end))
        base.format_cell(title_cell, title, size=10.5, bold=True, fill="D9EAF7")
        base.format_cell(body_cell, items, size=9.2, fill="F3F7FB")

    second = [
        (0, 1, "بازیابی، همکاری و کنترل هزینه", "RAGLog [12]؛ AdaptiveLog [13]؛ FlexLog [10]"),
        (2, 3, "تجزیه و ساخت قالب", "LogPPT [24]؛ LogParser-LLM [23]"),
        (4, 5, "مرور، معیار و استقرار", "SLR [14]؛ AIOps واقعی [20]؛ OpsEval [25]؛ YuLan [26]؛ مرور Anomaly/OOD [27]"),
    ]
    for start, end, title, items in second:
        title_cell = table.cell(3, start).merge(table.cell(3, end))
        body_cell = table.cell(4, start).merge(table.cell(4, end))
