def add_chapter_content_all27(doc):
    base.add_heading(doc, "۲-۱ مقدمه", 2)
    base.add_body(doc, "لاگ‌های سیستمی گزارش‌های متنی یا نیمه‌ساخت‌یافته‌ای هستند که رخدادهای زمان اجرا، وضعیت اجزای سامانه، پیام‌های هشدار و اطلاعات عیب‌یابی را ثبت می‌کنند. این داده‌ها در بیشتر زیرساخت‌های نرم‌افزاری، شبکه‌ای و محاسباتی تولید می‌شوند و از منابع اصلی پایش سلامت سامانه، تشخیص خطا، تحلیل رخداد و یافتن علت ریشه‌ای به‌شمار می‌روند. با افزایش مقیاس سامانه‌ها، تعداد پیام‌ها و تنوع قالب‌های لاگ نیز افزایش یافته و تحلیل دستی دیگر پاسخ‌گوی جریان پیوسته داده نیست [14، 20، 21].")
    base.add_body(doc, "پژوهش تشخیص ناهنجاری لاگ از روش‌های قاعده‌محور و آماری به مدل‌های یادگیری توالی، مدل‌های زبانی پیش‌آموزش‌دیده و سپس مدل‌های زبانی بزرگ گسترش یافته است. DeepLog توالی رخدادها را با LSTM مدل می‌کند؛ LogBERT و BERT-Log بازنمایی دوطرفه BERT را وارد مسئله می‌کنند؛ و پژوهش‌هایی مانند LogPrompt، LogGPT، RAGLog و Hybrid Prompting از توان پیروی از دستور و درک معنایی LLM استفاده می‌کنند [1–6، 12، 18، 19، 21].")
    base.add_body(doc, "مدل زبانی در مطالعات مرورشده نقش واحدی ندارد. در برخی پژوهش‌ها طبقه‌بند مستقیم است؛ در برخی دیگر برای پیش‌بینی رخداد بعدی آموزش داده می‌شود؛ در گروهی برای تولید داده یا توضیح به‌کار می‌رود؛ و در چارچوب‌های ترکیبی، مدل بزرگ فقط نمونه‌های دشوار را دریافت می‌کند. مرور نظام‌مند حوزه لاگ و مرور عمومی تشخیص ناهنجاری و داده خارج از توزیع نیز همین تنوع نقش را به‌عنوان یکی از محورهای اصلی دسته‌بندی معرفی می‌کنند [14، 27].")
    base.add_body(doc, "به همین دلیل، مقایسه پژوهش‌ها باید افزون بر نام مدل، نوع ورودی، واحد تصمیم، نیاز به آموزش، سازوکار آماده‌سازی، نوع استقرار و روش کنترل هزینه را در نظر بگیرد. برای نمونه، عدد F1 حاصل از طبقه‌بندی خط‌به‌خط با نتیجه یک پنجره یک‌دقیقه‌ای یا توالی مبتنی بر نشست هم‌معنا نیست. همچنین کش تصمیم، بازیابی نمونه و واگذاری به مدل کوچک سه سازوکار متفاوت‌اند، هرچند هر سه تعداد یا هزینه فراخوانی LLM را کاهش می‌دهند [3، 10، 12، 13].")
    base.add_body(doc, "دامنه پژوهش حاضر به مجموعه‌داده BGL و مدل Qwen2.5:7B-Instruct محدود است. مدل از طریق Ollama و به‌صورت محلی اجرا می‌شود و تنظیم دقیق انجام نمی‌گیرد. مقایسه میان دو روش Hybrid و Prompt-only صورت می‌گیرد: در روش نخست قواعد قطعی پیش از فراخوانی LLM اعمال می‌شوند و در روش دوم همان دانش دامنه در متن پرامپت قرار می‌گیرد. در هر دو روش، نرمال‌سازی، کش سطح قالب و اعتبارسنجی خروجی ثابت نگه داشته می‌شوند.")
    base.add_body(doc, "این فصل ابتدا مبانی نظری موردنیاز را تعریف می‌کند. سپس هر ۲۷ مقاله موجود در پوشه پژوهش به‌صورت مستقل مرور می‌شود؛ حتی دو مقاله [1] و [6] که دو نسخه هم‌پوشان از خط پژوهشی LogPrompt هستند، جداگانه معرفی و رابطه آن‌ها تصریح می‌شود. در ادامه، جدول ۲۷ ردیفی، شکل ارتباط مطالعات، تحلیل مقایسه‌ای و شکاف تحقیقاتی ارائه می‌گردد. تمام تعریف‌ها و گزاره‌های مربوط به مطالعات به منابع ارجاع داده شده‌اند و نتایج آزمایش‌های در حال تکمیل پروژه وارد پیشینه نشده‌اند.")

    base.add_heading(doc, "۲-۲ مبانی نظری و مفاهیم موردنیاز", 2)
    base.add_heading(doc, "۲-۲-۱ ماهیت و ساختار لاگ سیستمی", 3)
    base.add_body(doc, "یک پیام لاگ معمولاً شامل سرآیند و بدنه است. سرآیند می‌تواند زمان، سطح شدت، نام مؤلفه، شناسه فرایند یا گره را در بر گیرد و بدنه، شرح رخداد برنامه و پارامترهای زمان اجرا را بیان کند. مطالعات LogPPT و LogParser-LLM بدنه را به بخش ثابت یا «قالب لاگ» و بخش متغیر یا «پارامتر» تفکیک می‌کنند. کلمات ثابت نوع رخداد را نشان می‌دهند و مقادیری مانند شناسه بلوک، نشانی شبکه، مسیر فایل و زمان اجرا میان نمونه‌ها تغییر می‌کنند [23، 24].")
    base.add_body(doc, "لاگ خام به دلیل وجود مقادیر پویا، اختصارات، کدهای خطا و قالب‌های متفاوت، متن طبیعی کامل نیست. بااین‌حال، روابط میان کلمات ثابت و زمینه عملیاتی حامل اطلاعات معنایی‌اند. مدل‌های زبانی پیش‌آموزش‌دیده و LLMها تلاش می‌کنند این اطلاعات را از متن یا توالی استخراج کنند، درحالی‌که روش‌های آماری معمولاً ابتدا پیام را به شناسه قالب یا بردار فراوانی تبدیل می‌کنند [4، 14، 18، 19].")

    base.add_heading(doc, "۲-۲-۲ مفهوم ناهنجاری و سطوح تحلیل", 3)
    base.add_body(doc, "در تشخیص ناهنجاری، مشاهده‌ای ناهنجار تلقی می‌شود که با الگوی رفتار عادی آموخته‌شده یا قواعد تعریف‌شده سازگار نباشد. مرور Xu و Ding میان تغییر هم‌توزیعی که به ناهنجاری منجر می‌شود و تغییر معناییِ داده خارج از توزیع تمایز می‌گذارد و نقش LLM را در دو گروه «LLM برای تشخیص» و «LLM برای تولید» طبقه‌بندی می‌کند [27]. در حوزه لاگ، ناهنجاری می‌تواند در متن یک پیام، فراوانی قالب‌ها، ترتیب رخدادها یا معنای یک پنجره زمانی ظاهر شود [14].")
    base.add_body(doc, "واحد تحلیل در ادبیات شامل خط منفرد، قالب، پنجره زمانی، توالی مبتنی بر گره و نشست است. ADALog پیام منفرد را مستقل تحلیل می‌کند؛ DeepLog و LogBERT بر توالی رخدادها تکیه دارند؛ BERT-Log در BGL پنجره لغزان مبتنی بر گره می‌سازد؛ و Hybrid Prompting از پنجره یک‌دقیقه‌ای استفاده می‌کند [3، 18، 19، 21، 22]. واحد تحلیل، نحوه تعریف TP، FP، TN و FN و قابلیت مقایسه نتیجه را تعیین می‌کند.")

    base.add_heading(doc, "۲-۲-۳ مجموعه‌داده BGL", 3)
    base.add_body(doc, "مجموعه‌داده Blue Gene/L یا BGL از ابررایانه Blue Gene/L در آزمایشگاه ملی لارنس لیورمور گردآوری شده است. این مجموعه ۴٬۷۴۷٬۹۶۳ پیام دارد و ۳۴۸٬۴۶۰ پیام، حدود ۷٫۳۴ درصد، با برچسب هشدار به‌عنوان ناهنجار مشخص شده‌اند [2، 18، 19]. برچسب اصلی در ابتدای هر خط قرار دارد و برای ارزیابی قابل استفاده است، اما حضور آن در ورودی مدل باعث نشت پاسخ می‌شود؛ بنابراین در پژوهش حاضر پیش از تشکیل متن ورودی حذف می‌گردد.")
    base.add_body(doc, "پروتکل‌های BGL در منابع یکسان نیستند. LogBERT پنجره زمانی پنج‌دقیقه‌ای با میانگین ۵۶۲ رخداد ایجاد می‌کند؛ BERT-Log شناسه گره، اندازه پنجره و گام را به‌کار می‌گیرد؛ Hybrid Prompting پنجره یک‌دقیقه‌ای و نمونه متوازن هزار توالی عادی و هزار توالی ناهنجار می‌سازد؛ و ADALog پس از پاک‌سازی، مجموعه‌ای از پیام‌های یکتای عادی و ناهنجار را در سطح خط بررسی می‌کند [3، 18، 19، 22].")
    base.add_body(doc, "در پژوهش LogGPT مبتنی بر ChatGPT، به دلیل محدودیت نرخ API، دو هزار لاگ متوالی از بخش آزمون انتخاب شده است [2]. در RAGLog نیز برای ساخت خوشه‌ها و پایگاه برداری از نمونه‌گیری و K-means استفاده می‌شود [12]. این تفاوت‌ها نشان می‌دهد عبارت «ارزیابی روی BGL» باید همراه با واحد تحلیل، نمونه‌گیری، پنجره و نسبت کلاس‌ها گزارش شود.")

    base.add_heading(doc, "۲-۲-۴ تجزیه، پاک‌سازی و نرمال‌سازی", 3)
    base.add_body(doc, "تجزیه لاگ فرایند تبدیل پیام خام به قالب ثابت و فهرست پارامترهای متغیر است. روش‌های سنتی از فراوانی، شباهت و قواعد نحوی استفاده می‌کنند. LogPPT مدل RoBERTa را با پرامپت‌تیونینگ و تعداد اندکی نمونه برای برچسب‌گذاری توکن‌های پارامتر تنظیم می‌کند؛ LogParser-LLM نیز معناشناسی LLM را با درخت پیشوند ترکیب می‌کند تا فقط برای الگوهای نیازمند تصمیم فراخوانی انجام شود [23، 24].")
    base.add_body(doc, "نرمال‌سازی پژوهش حاضر یک parser خوشه‌بندی‌شده کامل نیست، بلکه نگاشتی قطعی از مقادیر پویا به جانشین‌های ثابت برای تشکیل قالب قابل کش است. شناسه‌های گره، نشانی IP، مقادیر هگزادسیمال، تاریخ و زمان، مسیرها و اعداد پویا پوشانده می‌شوند. صفر و غیرصفر به‌ترتیب با <ZERO> و <NON_ZERO> متمایز می‌مانند، زیرا برخی رخدادها از وضعیت عددی خود معنا می‌گیرند. این تصمیم با اصل تفکیک قالب و پارامتر در مطالعات تجزیه سازگار است [23، 24].")
    base.add_body(doc, "کیفیت نرمال‌سازی بر دو متغیر اثر دارد: اطلاعاتی که برای تشخیص باقی می‌ماند و تعداد قالب‌های یکتایی که به مدل فرستاده می‌شود. ماسک بیش‌ازحد ممکن است واژه یا مقدار معنادار را حذف کند؛ ماسک کمتر نیز پیام‌های هم‌معنا را به کلیدهای متعدد تبدیل می‌کند. LogLAA و LogParser-LLM نیز اثر کیفیت تجزیه بر تحلیل پایین‌دستی و ضرورت کنترل دانه‌بندی قالب را گزارش می‌کنند [17، 23].")

    base.add_heading(doc, "۲-۲-۵ پارادایم‌های یادگیری در تشخیص ناهنجاری لاگ", 3)
    base.add_body(doc, "روش نظارت‌شده از نمونه‌های عادی و ناهنجار برچسب‌خورده برای یادگیری مرز تصمیم استفاده می‌کند. BERT-Log نمونه‌ای از تنظیم نظارت‌شده است [18]. روش نیمه‌نظارتی از مقدار محدودی داده برچسب‌خورده و داده بدون برچسب بهره می‌گیرد؛ SemiRALD این رویکرد را با RoBERTa و BiLSTM ترکیب می‌کند [16]. روش خودنظارتی از یک وظیفه کمکی مانند پیش‌بینی توکن یا رخداد ماسک‌شده برای یادگیری الگوی عادی استفاده می‌کند؛ LogBERT، LogFiT و ADALog در این دسته قرار می‌گیرند [8، 19، 22].")
    base.add_body(doc, "تنظیم دقیق کامل، تنظیم پارامترکارا و یادگیری درون‌متنی سه شیوه متفاوت سازگارکردن مدل زبانی با دامنه‌اند. LogLLM و LogGPT مبتنی بر GPT مراحل آموزشی اختصاصی دارند؛ LLM-LADE و پژوهش Lim و همکاران از LoRA، ReFT یا سایر روش‌های PEFT استفاده می‌کنند؛ و LogPrompt و LogGPT مبتنی بر ChatGPT بدون تغییر وزن، دستور و نمونه را در پرامپت قرار می‌دهند [1، 2، 4–7، 9].")

    base.add_heading(doc, "۲-۲-۶ مدل‌های ترتیبی، Transformer و مدل‌های زبانی", 3)
    base.add_body(doc, "مدل ترتیبی احتمال رخداد بعدی یا سازگاری کل توالی را برآورد می‌کند. DeepLog با LSTM رخداد بعدی را از تاریخچه پیش‌بینی و انحراف را علامت‌گذاری می‌کند [21]. Transformer با سازوکار توجه امکان استفاده از زمینه دورتر و پردازش موازی‌تر را فراهم می‌کند. LogBERT با زمینه دوطرفه و دو هدف خودنظارتی و BERT-Log با بازنمایی BERT و طبقه‌بند متصل، این معماری را برای لاگ به‌کار گرفته‌اند [18، 19].")
    base.add_body(doc, "LLMهای دستورمحور عمدتاً بر معماری Transformer خودبازگشتی بنا می‌شوند و پاسخ را براساس دستور متنی تولید می‌کنند. YuLan فرایند توسعه یک مدل متن‌باز ۱۲ میلیارد پارامتری را در سه مرحله پیش‌آموزی، تنظیم دستوری و هم‌ترازی انسانی تشریح می‌کند و قابلیت یادگیری درون‌متنی را یکی از پیامدهای پس‌آموزی می‌داند [26]. این مقاله آشکارساز لاگ نیست، اما برای توضیح منشأ توانایی مدل‌های دستورمحور در پیروی از پرامپت استفاده می‌شود.")

    base.add_heading(doc, "۲-۲-۷ نقش‌های LLM در خط لوله تحلیل لاگ", 3)
    base.add_body(doc, "در یک خط لوله لاگ، LLM می‌تواند parser، طبقه‌بند، تولیدکننده داده، تبیین‌گر یا هماهنگ‌کننده باشد. LogParser-LLM و LogPPT در مرحله استخراج قالب قرار دارند [23، 24]. LogGPT، LogPrompt و Hybrid Prompting تصمیم تشخیص را مستقیماً از مدل دریافت می‌کنند [1–3، 6]. LLM-LADE از LLM برای افزایش داده و توضیح استفاده می‌کند و LogLAA توضیح رخداد را پس از تشخیص تولید می‌کند [7، 17].")
    base.add_body(doc, "در سامانه‌های چندمدلی، LLM لزوماً برای همه نمونه‌ها اجرا نمی‌شود. AdaptiveLog عدم‌قطعیت مدل کوچک را معیار ارجاع به مدل بزرگ قرار می‌دهد [13]. FlexLog نتیجه چند مدل یادگیری ماشین را با Mistral، بازیابی و کش ترکیب می‌کند [10]. LogSynergy نیز تفسیر رخداد با LLM را برای ساخت بازنمایی قابل انتقال میان سامانه‌ها به‌کار می‌برد [15].")

    base.add_heading(doc, "۲-۲-۸ Qwen2.5:7B-Instruct", 3)
    base.add_body(doc, "Qwen2.5 خانواده‌ای از مدل‌های باز با نسخه‌های پایه و دستورمحور در اندازه‌های ۰٫۵ تا ۷۲ میلیارد پارامتر است. گزارش فنی Qwen2.5 پیش‌آموزی بر حدود ۱۸ تریلیون توکن و پس‌آموزی با بیش از یک میلیون نمونه تنظیم دستوری و مراحل تقویت یادگیری را شرح می‌دهد. نسخه 7B حدود ۶٫۵ میلیارد پارامتر غیرتعبیه‌ای دارد و نسخه Instruct برای پیروی از دستور و تولید پاسخ ساخت‌یافته آماده شده است [28].")
    base.add_body(doc, "Qwen2.5:7B-Instruct در پژوهش حاضر بدون تنظیم دقیق و با وزن‌های ثابت استفاده می‌شود. ثابت نگه‌داشتن نسخه مدل، کوانتیزه‌سازی، دما و گزینه‌های تولید در دو روش ضروری است؛ زیرا در غیر این صورت اختلاف خروجی می‌تواند به تغییر مدل یا تنظیمات تولید نسبت داده شود، نه محل اعمال قاعده. مقاله Hybrid Prompting از Qwen3-Embedding-8B برای تعبیه و GPT-4o-mini برای تصمیم استفاده کرده است و از نظر نقش مدل با این پژوهش تفاوت دارد [3].")

    base.add_heading(doc, "۲-۲-۹ مهندسی پرامپت، یادگیری درون‌متنی و خروجی", 3)
    base.add_body(doc, "پرامپت شامل تعریف وظیفه، زمینه دامنه، معنای برچسب‌ها، نمونه‌های احتمالی و قرارداد خروجی است. LogGPT مبتنی بر ChatGPT پنج پرسش درباره نوع پرامپت، اندازه پنجره، دانش انسانی، مقایسه با روش‌های عمیق و تبیین‌پذیری مطرح می‌کند [2]. LogPrompt اثر پرامپت ساده، پرامپت دارای دانش دامنه و زنجیره استدلال را بر تجزیه و تشخیص بررسی می‌کند [1، 6].")
    base.add_body(doc, "Few-shot نمونه‌های برچسب‌خورده را در خود پرامپت قرار می‌دهد و به تغییر وزن مدل نیاز ندارد. RAGLog نمونه‌های عادی مرتبط را از پایگاه برداری بازیابی می‌کند [12] و Hybrid Prompting نزدیک‌ترین نمونه عادی را همراه با شواهد رخداد و توالی در متن قرار می‌دهد [3]. OpsEval نیز حساسیت وظایف عملیات فناوری اطلاعات به self-consistency، chain-of-thought و in-context learning را در یک معیار مستقل بررسی می‌کند [25].")
    base.add_body(doc, "قرارداد خروجی پژوهش حاضر فقط {\"label\":\"0\"} یا {\"label\":\"1\"} را معتبر می‌داند. متن اضافی، JSON ناقص یا برچسب دیگر با وضعیت INVALID ثبت و کش نمی‌شود. مستندات Ollama امکان تعیین قالب یا طرح JSON و استفاده از دمای صفر برای کاهش نوسان را بیان می‌کنند [29]. اعتبارسنجی در برنامه مستقل از پذیرش ظاهری پاسخ انجام می‌شود.")

    base.add_heading(doc, "۲-۲-۱۰ بازیابی، کش و کنترل هزینه استنتاج", 3)
    base.add_body(doc, "بازیابی و کش دو سازوکار متفاوت‌اند. بازیابی، نمونه یا دانش مرتبط را برای ساخت زمینه پرامپت پیدا می‌کند؛ RAGLog و AdaptiveLog از این الگو استفاده می‌کنند [12، 13]. کش، پاسخ معتبر یک ورودی پایدار را نگه می‌دارد تا در مشاهده تکراری مدل دوباره اجرا نشود؛ FlexLog کش را در کنار RAG و مدل‌های یادگیری ماشین به‌کار می‌گیرد [10].")
    base.add_body(doc, "در پژوهش حاضر کش در سطح قالب نرمال‌شده است. کلید شامل نسخه پرامپت، نام و نسخه مدل، قالب نرمال‌شده و در صورت فعال بودن، فیلدهای مؤلفه، شدت و دسته است. بنابراین تصمیم یک مدل یا پرامپت قدیمی به اجرای جدید منتقل نمی‌شود. نرخ برخورد، عدم برخورد، کلیدهای یکتا و منبع تصمیم برای تحلیل جداگانه اثر کش ثبت می‌شوند.")
    base.add_body(doc, "AdaptiveLog با استفاده از مدل کوچک و ارجاع موارد نامطمئن به LLM کاهش هزینه فراخوانی تا ۷۳ درصد را گزارش می‌کند [13]. LogParser-LLM نیز با درخت پیشوند و تجمیع پیام‌های مشابه، در LogPub با میانگین ۳٫۶ میلیون پیام در هر مجموعه به‌طور متوسط فقط ۲۷۲٫۵ فراخوانی LLM انجام داده است [23]. این اعداد نشان‌دهنده اهمیت گزارش فراخوانی و زمان در کنار معیارهای طبقه‌بندی هستند.")

    base.add_heading(doc, "۲-۲-۱۱ استنتاج محلی با Ollama", 3)
    base.add_body(doc, "Ollama اجرای محلی مدل و دسترسی برنامه‌نویسی از طریق API پیش‌فرض localhost:11434/api را فراهم می‌کند. پاسخ API می‌تواند زمان کل، زمان بارگذاری، شمار توکن پرامپت و خروجی و مدت ارزیابی هر بخش را گزارش کند [29]. ثبت این داده‌ها امکان تفکیک زمان بارگذاری مدل از زمان پردازش پرامپت و تولید پاسخ را فراهم می‌سازد.")
    base.add_body(doc, "استقرار محلی از ارسال لاگ به سرویس خارجی جلوگیری و کنترل نسخه مدل را ممکن می‌کند. مطالعه کاربرد واقعی De la Cruz Cabello و همکاران نیز LogBERT را برای محیط دارای محدودیت محرمانگی به‌صورت درون‌سازمانی مستقر کرده است [20]. تفاوت آن مطالعه با پژوهش حاضر در نوع مدل و آموزش است: مدل آن‌ها روی syslog عادی آموزش می‌بیند، درحالی‌که Qwen در این پژوهش بدون تنظیم اختصاصی استفاده می‌شود.")

    base.add_heading(doc, "۲-۲-۱۲ دو معماری Hybrid و Prompt-only در پژوهش حاضر", 3)
    base.add_body(doc, "در روش Hybrid، پس از استخراج فیلدها، حذف برچسب و نرمال‌سازی، کش بررسی می‌شود. اگر کلید موجود نباشد، مجموعه محدود قواعد قطعی با اطمینان بالا اعمال می‌شود. فقط نمونه‌هایی که guard برای آن‌ها تصمیم ندارد به Qwen ارسال می‌شوند. پاسخ معتبر در کش قرار می‌گیرد و منبع تصمیم به‌صورت cache، guard یا llm ثبت می‌شود.")
    base.add_body(doc, "در روش Prompt-only، guard قطعی غیرفعال است و دانش دامنه در پرامپت قرار می‌گیرد. نرمال‌سازی، کش، نسخه مدل، قرارداد JSON و ترتیب داده ثابت می‌مانند. در نتیجه متغیر اصلی مقایسه محل اعمال دانش قاعده است. اصطلاح Hybrid در این پژوهش با Hybrid Prompting تفاوت دارد؛ مقاله [3] شواهد سطح رخداد، توالی و نمونه بازیابی‌شده را در یک پرامپت ترکیب می‌کند و تصمیم آن در سطح توالی است.")

    base.add_heading(doc, "۲-۲-۱۳ معیارهای ارزیابی", 3)
    base.add_body(doc, "در طبقه‌بندی دودویی، TP ناهنجاری درست شناسایی‌شده، TN خط عادی درست، FP خط عادی با برچسب ناهنجار و FN ناهنجاری ازدست‌رفته است. Accuracy نسبت کل تصمیم‌های درست، Precision سهم پیش‌بینی‌های ناهنجار درست، Recall سهم ناهنجاری‌های کشف‌شده و F1 میانگین هارمونیک Precision و Recall است [2، 3، 18].")
    base.add_body(doc, "Accuracy = (TP + TN) / (TP + TN + FP + FN)", center=True, ltr=True, size=12)
    base.add_body(doc, "Precision = TP / (TP + FP)     Recall = TP / (TP + FN)     F1 = 2 × Precision × Recall / (Precision + Recall)", center=True, ltr=True, size=12)
    base.add_body(doc, "به‌علت نامتوازن بودن BGL، Accuracy باید همراه Precision، Recall و F1 گزارش شود. نرخ INVALID، زمان پاسخ، تعداد فراخوانی LLM، منبع تصمیم و نرخ برخورد کش نیز برای این پژوهش ضروری‌اند. این شاخص‌ها مانع آن می‌شوند که کاهش فراخوانی ناشی از کش یا guard با بهبود خود طبقه‌بند اشتباه شود.")

    base.add_heading(doc, "۲-۲-۱۴ انواع الگوهای ناهنجاری در لاگ", 3)
    base.add_body(doc, "ناهنجاری رخدادی زمانی رخ می‌دهد که خود یک پیام یا قالب، مستقل از پیرامون آن، نشانه وضعیت غیرعادی باشد. وجود عبارت خطا، توقف مؤلفه، خرابی سخت‌افزار یا کد بازگشتی غیرمنتظره می‌تواند از این نوع باشد. ADALog بر همین سطح تمرکز می‌کند و احتمال بازسازی توکن‌های یک پیام را به امتیاز خط تبدیل می‌نماید [22]. طبقه‌بندی خط‌به‌خط پژوهش حاضر نیز ابتدا برای این سطح از ناهنجاری تعریف شده است.")
    base.add_body(doc, "ناهنجاری ترتیبی از کنار هم قرارگرفتن رخدادهایی ایجاد می‌شود که ممکن است هرکدام به‌تنهایی عادی باشند، اما ترتیب یا فاصله آن‌ها با الگوی عادی سازگار نباشد. DeepLog با پیش‌بینی رخداد بعدی و LogBERT با یادگیری زمینه دوطرفه، این نوع انحراف را هدف می‌گیرند [19، 21]. Hybrid Prompting نیز اطلاعات توالی را همراه رخدادهای دیده‌نشده در پرامپت قرار می‌دهد [3].")
    base.add_body(doc, "ناهنجاری کمّی به تغییر غیرعادی تعداد تکرار یک یا چند قالب در یک پنجره مربوط است. روش‌های مبتنی بر بردار شمارش و برخی مدل‌های ترکیبی، فراوانی رخداد را در کنار ترتیب یا معنا استفاده می‌کنند. LogLAA سه نوع بازنمایی شمارشی، ترتیبی و معنایی را به‌صورت هم‌زمان وارد آشکارساز می‌کند [17]. در تصمیم خط‌محور این پایان‌نامه، شمارش پنجره ورودی مستقیم Qwen نیست و این محدودیت باید هنگام تحلیل خطا در نظر گرفته شود.")
    base.add_body(doc, "ناهنجاری معنایی زمانی مطرح می‌شود که واژه‌ها یا مقادیر یک پیام از نظر نحوی مشابه نمونه عادی باشند، اما مفهوم آن‌ها وضعیت نامطلوبی را بیان کند. مطالعات LogPrompt، RAGLog و LogLLM استفاده از بازنمایی زبانی را برای بازیابی یا درک چنین تفاوتی بررسی کرده‌اند [1، 4، 6، 12]. حفظ صفر و غیرصفر در نرمال‌سازی پایان‌نامه برای جلوگیری از حذف بخشی از همین معنای عملیاتی انجام می‌شود.")
    base.add_body(doc, "لاگ ناپایدار به تغییر قالب، واژگان یا توزیع رخدادها پس از به‌روزرسانی نرم‌افزار یا تغییر پیکربندی اشاره دارد. مطالعات GPT روی LOGEVOL، LogLLM و FlexLog این مسئله را با انتقال نسخه، مدل زبانی یا ترکیب مدل‌ها بررسی کرده‌اند [4، 10، 11]. BGL در پایان‌نامه به‌عنوان یک مجموعه ثابت ارزیابی می‌شود و آزمون انتقال میان نسخه‌های نرم‌افزار خارج از دامنه است.")

    base.add_heading(doc, "۲-۲-۱۵ چالش‌های روش‌شناختی و اجرایی", 3)
    base.add_body(doc, "نامتوازن بودن کلاس‌ها یکی از چالش‌های اصلی است. در BGL سهم پیام‌های ناهنجار حدود ۷٫۳۴ درصد است [2، 19]. در چنین شرایطی، مدلی که بیشتر نمونه‌ها را عادی پیش‌بینی کند ممکن است Accuracy ظاهراً بالایی داشته باشد، اما Recall ناهنجاری پایین بماند. به همین دلیل، مطالعات BERT-Log و Hybrid Prompting معیارهای Precision، Recall و F1 را در کنار Accuracy یا به‌جای اتکای صرف به آن گزارش می‌کنند [3، 18].")
    base.add_body(doc, "انتقال خطای parser چالش دیگری است. اگر پارامتر به‌عنوان کلمه ثابت یا کلمه ثابت به‌عنوان پارامتر تشخیص داده شود، قالب نادرست به مدل پایین‌دستی می‌رسد. LogPPT و LogParser-LLM برای سنجش این مسئله Group Accuracy، Parsing Accuracy و معیارهای دانه‌بندی را به‌کار می‌گیرند [23، 24]. در پایان‌نامه، قواعد نرمال‌سازی باید جدا از کیفیت طبقه‌بندی ممیزی شوند.")
    base.add_body(doc, "نشت داده می‌تواند از ورود برچسب به متن، هم‌پوشانی نمونه‌های آموزش و آزمون یا تکرار قالب یکسان در دو بخش ایجاد شود. ADALog داده‌های یکتای عادی را میان آموزش، تعیین آستانه و آزمون جدا می‌کند [22]. در این پایان‌نامه برچسب BGL قبل از ساخت پرامپت حذف می‌شود و کش فقط در محدوده همان اجرای تعریف‌شده و با کلید نسخه‌بندی‌شده به‌کار می‌رود.")
    base.add_body(doc, "پاسخ مولد ممکن است از قرارداد خروجی پیروی نکند یا میان اجراها تغییر کند. مطالعات پرامپتی نشان می‌دهند متن دستور و درخواست تبیین بر نتیجه اثر دارد [1، 2، 6، 25]. استفاده از دمای صفر، طرح JSON، اعتبارسنجی برچسب و ثبت INVALID در پایان‌نامه برای قابل‌اندازه‌گیری کردن این رفتار انجام می‌شود [29].")
    base.add_body(doc, "تبیین‌پذیری در منابع به چند معنا به‌کار رفته است. LogPrompt از مدل می‌خواهد دلیل تصمیم را تولید کند [1، 6]؛ LLM-LADE تشخیص و توضیح را هم‌زمان آموزش می‌دهد [7]؛ و LogLAA پس از آشکارسازی از LLM برای توضیح استفاده می‌کند [17]. خروجی پایان‌نامه عمداً دودویی است، بنابراین تبیین در سطح ثبت منبع تصمیم، قالب نرمال‌شده و قاعده فعال‌شده دنبال می‌شود، نه تولید شرح آزاد.")
    base.add_body(doc, "محرمانگی، بازتولیدپذیری و هزینه نیز به هم مرتبط‌اند. سرویس تجاری امکان تغییر نسخه مدل و محدودیت نرخ دارد، درحالی‌که استقرار محلی کنترل بیشتری بر مدل و داده فراهم می‌کند [2، 20]. بااین‌حال، استقرار محلی به ثبت سخت‌افزار، کوانتیزه‌سازی، نسخه Ollama و پارامترهای تولید نیاز دارد تا نتیجه قابل بازتولید باشد [28، 29].")

    base.add_heading(doc, "۲-۳ پیشینه تحقیق", 2)
    base.add_heading(doc, "۲-۳-۱ دامنه و شیوه مرور مطالعات", 3)
    base.add_body(doc, "پیشینه این فصل شامل تمام ۲۷ فایل مقاله موجود در پوشه پژوهش است. مقالات براساس نقش اصلی روش در شش دسته قرار گرفته‌اند: روش‌های ترتیبی و پیش‌آموزش‌دیده؛ آموزش و تنظیم LLM؛ پرامپت؛ بازیابی و کنترل هزینه؛ تجزیه لاگ؛ و مرور، معیار، مدل پایه یا استقرار واقعی. این دسته‌بندی با محورهای مطرح‌شده در مرور نظام‌مند لاگ [14] و مرور LLM برای تشخیص ناهنجاری [27] سازگار است.")
    base.add_body(doc, "دو فایل [1] و [6] نسخه‌های هم‌پوشان یک خط پژوهشی با نام LogPrompt هستند. مطابق درخواست پوشش همه مقالات، هر دو به‌صورت مستقل مرور و در جدول درج شده‌اند؛ بااین‌حال هنگام جمع‌بندی شواهد به‌عنوان دو روش متفاوت شمرده نمی‌شوند. همچنین مقالات OpsEval [25] و YuLan [26] آشکارساز مستقیم لاگ نیستند، اما به‌ترتیب برای مبانی ارزیابی LLM در عملیات و معماری مدل متن‌باز استفاده می‌شوند.")

    base.add_heading(doc, "۲-۳-۲ روش‌های ترتیبی و مدل‌های زبانی پیش‌آموزش‌دیده", 3)
    add_labeled_body(doc, "مقاله ۲۱ ـ DeepLog: ", "Du و همکاران لاگ را مانند یک توالی زبان در نظر گرفتند و شبکه LSTM را برای پیش‌بینی رخداد بعدی از روی تاریخچه رخدادهای عادی آموزش دادند. اگر رخداد واقعی در مجموعه رخدادهای محتمل مدل قرار نگیرد، توالی به‌عنوان مشکوک گزارش می‌شود. مقاله علاوه بر تشخیص، به‌روزرسانی افزایشی مدل و ساخت جریان‌های اجرایی برای کمک به عیب‌یابی را توضیح می‌دهد.", citation="[21]")
    base.add_body(doc, "ارزیابی DeepLog روی داده HDFS و OpenStack نشان داد مدل ترتیبی می‌تواند وابستگی رخدادها را بهتر از روش‌های آماری مبنا ثبت کند [21]. این روش به parser، تشکیل کلید لاگ و توالی معتبر نیاز دارد و هدف آن تصمیم مستقل برای هر خط نیست. در پژوهش حاضر، ترتیب رخداد به‌عنوان ورودی مستقیم مدل استفاده نمی‌شود و واحد تصمیم خط BGL است؛ بنابراین DeepLog خط پایه مفهومی خانواده ترتیبی محسوب می‌شود، نه روش هم‌پروتکل.")

    add_labeled_body(doc, "مقاله ۱۹ ـ LogBERT: ", "Guo، Yuan و Wu چارچوب خودنظارتی LogBERT را با دو وظیفه طراحی کردند: پیش‌بینی کلید لاگ ماسک‌شده و کمینه‌سازی حجم ابرکره بازنمایی توالی‌های عادی. زمینه دوطرفه BERT باعث می‌شود بازنمایی هر رخداد از قبل و بعد توالی استفاده کند و وظیفه ابرکره نیز توالی‌های عادی را در فضای بازنمایی به یکدیگر نزدیک می‌سازد.", citation="[19]")
    base.add_body(doc, "LogBERT روی HDFS، BGL و Thunderbird ارزیابی شده است. برای BGL پنجره پنج‌دقیقه‌ای ساخته شده و مقاله از حدود پنج هزار توالی عادی برای آموزش استفاده می‌کند؛ میانگین طول توالی BGL نیز ۵۶۲ رخداد گزارش شده است [19]. وابستگی به آموزش روی داده عادی و ساخت پنجره تفاوت اصلی آن با Qwen بدون تنظیم و تصمیم خط‌به‌خط در پژوهش حاضر است.")

    add_labeled_body(doc, "مقاله ۱۸ ـ BERT-Log: ", "Chen و Liao پیام‌های تجزیه‌شده را با BERT بازنمایی و مدل را همراه یک لایه تمام‌متصل برای طبقه‌بندی تنظیم کردند. در HDFS توالی‌ها با شناسه بلوک و در BGL با شناسه گره، اندازه پنجره و گام ساخته می‌شوند. مدل از اطلاعات متن و زمینه توالی برای تفکیک رفتار عادی و ناهنجار استفاده می‌کند.", citation="[18]")
    base.add_body(doc, "مقاله F1 برابر ۹۹٫۳ درصد برای HDFS و ۹۹٫۴ درصد برای BGL را در پروتکل خود گزارش می‌کند [18]. این نتیجه به آموزش نظارت‌شده، parser و پنجره BGL وابسته است و مستقیماً با تشخیص خط‌محور بدون fine-tuning قابل مقایسه نیست. اهمیت BERT-Log برای پژوهش حاضر نشان‌دادن ظرفیت بازنمایی زبانی در BGL و ضرورت گزارش دقیق پروتکل پنجره است.")

    add_labeled_body(doc, "مقاله ۸ ـ LogFiT: ", "Almodovar و همکاران LogFiT را بر پایه مدل زبانی تنظیم‌شده با وظیفه مدل‌سازی توکن ماسک‌شده ارائه کردند. مدل فقط روی لاگ‌های عادی آموزش می‌بیند و در آزمون، توکن‌های پیام یا توالی را پیش‌بینی می‌کند. اگر توکن واقعی خارج از مجموعه top-k پیش‌بینی باشد، شواهد ناهنجاری افزایش می‌یابد.", citation="[8]")
    base.add_body(doc, "LogFiT روی HDFS، BGL و Thunderbird بررسی شده و هدف آن کاهش نیاز به نمونه ناهنجار برچسب‌خورده است [8]. با وجود استفاده از مدل زبانی، روش مولد دستورمحور نیست و به تنظیم روی لاگ مقصد نیاز دارد. در مقابل، پژوهش حاضر وزن‌های Qwen را ثابت نگه می‌دارد و پاسخ دودویی را از پرامپت دریافت می‌کند.")

    add_labeled_body(doc, "مقاله ۲۲ ـ ADALog: ", "Pospieszny و همکاران چارچوبی تطبیقی و بدون نظارت برای تحلیل پیام‌های خام و مستقل از توالی پیشنهاد کردند. DistilBERT با وظیفه MLM روی پیام‌های عادی تنظیم می‌شود؛ احتمال بازسازی توکن‌ها به امتیاز سطح پیام تبدیل و آستانه با صدک خطاهای داده عادی تعیین می‌گردد. روش به parser یا پیوستگی توالی وابسته نیست.", citation="[22]")
    base.add_body(doc, "ADALog روی BGL، Thunderbird و Spirit ارزیابی و اثر نرخ ماسک، پاک‌سازی و موقعیت توکن‌ها را با مطالعات حذف مؤلفه بررسی کرده است [22]. نزدیک‌بودن واحد تصمیم آن به سطح خط برای این پایان‌نامه مهم است، اما سازوکار تصمیم متفاوت است: ADALog به fine-tuning DistilBERT و امتیاز بازسازی متکی است، درحالی‌که پژوهش حاضر از Qwen دستورمحور، JSON و کش قالب استفاده می‌کند.")

    base.add_heading(doc, "۲-۳-۳ آموزش، تنظیم پارامترکارا و انتقال LLM", 3)
    add_labeled_body(doc, "مقاله ۵ ـ Log Anomaly Detection via GPT: ", "Han، Yuan و Trabelsi مدلی با نام LogGPT ارائه کردند که GPT را برای پیش‌بینی رخداد بعدی آموزش می‌دهد و سپس با یادگیری تقویتی، هدف تولید را به تصمیم تشخیص ناهنجاری نزدیک می‌کند. طراحی روش از توان مدل خودبازگشتی برای یادگیری توالی رخداد و از بازخورد پاداش برای اصلاح مرز تصمیم استفاده می‌کند.", citation="[5]")
    base.add_body(doc, "ارزیابی مقاله روی HDFS، BGL و Thunderbird انجام شده است [5]. اشتراک نام آن با مقاله [2] نباید به یکسان‌انگاری روش‌ها منجر شود؛ مقاله [5] روش آموزش و یادگیری تقویتی است، ولی مقاله [2] ChatGPT را با پرامپت بررسی می‌کند. پژوهش حاضر از نظر نبود آموزش به مقاله [2] نزدیک‌تر است.")

    add_labeled_body(doc, "مقاله ۴ ـ LogLLM: ", "Guan و همکاران LogLLM را با سه جزء اصلی طراحی کردند: BERT برای استخراج بردارهای معنایی، یک projector برای نگاشت بازنمایی و LLaMA به‌عنوان طبقه‌بند. آماده‌سازی با قواعد منظم انجام می‌شود و فرایند آموزشی چندمرحله‌ای برای هم‌ترازکردن بازنمایی BERT و فضای LLaMA به‌کار می‌رود.", citation="[4]")
    base.add_body(doc, "روش روی HDFS، BGL، Liberty و Thunderbird و در سناریوهای لاگ ناپایدار ارزیابی شده است [4]. LogLLM نشان می‌دهد ترکیب encoder کوچک‌تر با LLM می‌تواند اطلاعات معنایی و تصمیم را جدا کند، اما نیازمند آموزش projector و LLaMA است. پژوهش حاضر بدون آموزش، مستقیماً قالب نرمال‌شده را به Qwen می‌دهد.")

    add_labeled_body(doc, "مقاله ۷ ـ LLM-LADE: ", "Zhang و همکاران چارچوب سه‌مرحله‌ای شامل افزایش داده، تنظیم پارامترکارا و بهینه‌سازی برخط ارائه کردند. GPT-4 با پرامپت few-shot برای تولید نمونه و Llama3-8B با LoRA برای آشکارساز استفاده می‌شود. مدل علاوه بر برچسب ناهنجاری، توضیح متنی تولید می‌کند و دانش حاصل از نمونه‌های جدید در یک پایگاه دانش افزایشی نگه‌داری می‌شود.", citation="[7]")
    base.add_body(doc, "LLM-LADE تشخیص و توضیح را در یک فرایند مشترک قرار می‌دهد و سازوکار برخط را برای سازگاری با تغییرات پیشنهاد می‌کند [7]. در پژوهش حاضر خروجی برای جلوگیری از ابهام فقط برچسب JSON است و توضیح تولید نمی‌شود؛ همچنین بهینه‌سازی برخط یا LoRA وجود ندارد. این تفاوت دامنه سنجش را به کیفیت دودویی و هزینه استنتاج محدود می‌کند.")

    add_labeled_body(doc, "مقاله ۹ ـ تنظیم پارامترکارای مدل‌های زبانی: ", "Lim، Zhu و Pang عملکرد LoRA و ReFT را روی RoBERTa، GPT-2 و Llama-3 برای تشخیص ناهنجاری لاگ بررسی کردند. پژوهش فقط یک مدل پیشنهادی ارائه نمی‌کند، بلکه پایداری اجرا، کارایی نمونه، مقاومت در برابر لاگ ناپایدار و تعمیم میان مجموعه‌ها را در چهار مجموعه HDFS، BGL، Spirit و Thunderbird مقایسه می‌کند.", citation="[9]")
    base.add_body(doc, "نتایج مقاله نشان می‌دهد نوع مدل پایه و روش PEFT بر پایداری و انتقال اثر دارد [9]. این مطالعه معیار مناسبی برای تفکیک «استفاده از LLM» و «استفاده بدون تنظیم» فراهم می‌کند. Qwen در پژوهش حاضر با PEFT سازگار نمی‌شود و بنابراین نتیجه آن باید در طبقه prompt-only inference تفسیر شود، نه fine-tuned detection.")

    add_labeled_body(doc, "مقاله ۱۱ ـ Anomaly Detection on Unstable Logs with GPT Models: ", "Hadadi و همکاران مسئله تغییر قالب‌ها میان نسخه‌های نرم‌افزار را با GPT بررسی کردند. GPT-3 روی لاگ مقصد تنظیم و GPT-4 با مهندسی پرامپت استفاده شد. داده آزمایش از دو نسخه LOGEVOL-Hadoop تشکیل می‌شود تا اثر ناپایداری و انتقال میان نسخه‌ها سنجیده شود.", citation="[11]")
    base.add_body(doc, "در پروتکل مقاله، fine-tuning نسبت به prompt engineering نتیجه بهتری گزارش کرده است [11]. این یافته محدود به مدل‌ها و داده همان مطالعه است، اما نشان می‌دهد نبود تنظیم می‌تواند در تغییر توزیع هزینه عملکرد داشته باشد. پژوهش حاضر مسئله انتقال نسخه‌ای را آزمایش نمی‌کند و تمرکز آن بر دو محل اعمال قاعده در BGL ثابت است.")

    add_labeled_body(doc, "مقاله ۱۵ ـ LogSynergy: ", "Sui و همکاران برای انتقال آشکارساز به سامانه نرم‌افزاری جدید، تفسیر رخداد با LLM و استخراج ویژگی یکپارچه میان سامانه‌ها را ترکیب کردند. LLM تفاوت‌های نحوی رخدادها را به توصیف‌های هم‌معنا نزدیک می‌کند و سپس ویژگی‌های استانداردشده به طبقه‌بند انتقالی داده می‌شوند.", citation="[15]")
    base.add_body(doc, "LogSynergy با پنج هزار توالی برچسب‌خورده F1 بیش از ۸۹ درصد روی داده واقعی و بیش از ۸۳ درصد روی داده‌های عمومی گزارش می‌کند [15]. مسئله اصلی آن انتقال بین سامانه‌هاست، نه تصمیم بدون آموزش در یک مجموعه. ارتباط آن با پژوهش حاضر به نقش نرمال‌سازی معنایی و استفاده از LLM برای کاهش ناهمگونی ورودی مربوط می‌شود.")

    add_labeled_body(doc, "مقاله ۱۶ ـ SemiRALD: ", "Sun و همکاران چارچوب نیمه‌نظارتی SemiRALD را ارائه کردند. ChatGPT و یادگیری درون‌متنی برای تجزیه لاگ استفاده می‌شود و سپس بازنمایی RoBERTa همراه با BiLSTM توجه‌محور، الگوی توالی را برای طبقه‌بندی می‌آموزد. طراحی روش، مرحله تجزیه معنایی و طبقه‌بند آموزش‌پذیر را از یکدیگر جدا می‌کند.", citation="[16]")
    base.add_body(doc, "روش روی HDFS و BGL بررسی شده و مقاله میانگین بهبود F1 برابر ۷٫۳ و ۸٫۲ درصد را در مقایسه با دو گروه خط پایه گزارش می‌کند؛ بهبود در نسبت ۰٫۱ درصد داده برچسب‌خورده برجسته‌تر است [16]. Hybrid در نام این مقاله به ترکیب مدل زبانی و مدل ترتیبی اشاره دارد و با guard+LLM پژوهش حاضر متفاوت است.")

    add_labeled_body(doc, "مقاله ۱۷ ـ LogLAA: ", "Gao و همکاران چارچوب یکپارچه و تطبیقی LogLAA را برای تجزیه، تشخیص و توضیح طراحی کردند. parser از طول، فراوانی کلمات، جایگزینی متغیر و درخت پیشوند استفاده می‌کند؛ بازنمایی‌های شمارشی، ترتیبی و معنایی به CNN-LSTM دو‌توجهی داده می‌شوند؛ و LLM توضیح نتیجه را تولید می‌کند.", citation="[17]")
    base.add_body(doc, "مقاله افزایش ۰٫۸ درصدی کیفیت تجزیه، بهبود حدود ۶ درصدی Precision تشخیص نسبت به میانگین روش‌های مقایسه و امتیاز ۰٫۷ برای توضیح را گزارش می‌کند [17]. LogLAA سامانه‌ای چندمرحله‌ای و آموزش‌پذیر است؛ پژوهش حاضر بخش توضیح و مدل ترتیبی را حذف و بر کنترل تصمیم، کش و استنتاج محلی یک LLM ثابت تمرکز می‌کند.")

    base.add_heading(doc, "۲-۳-۴ مطالعات مبتنی بر پرامپت", 3)
    add_labeled_body(doc, "مقاله ۱ ـ نسخه اولیه LogPrompt: ", "Liu و همکاران در مقاله Interpretable Online Log Analysis Using Large Language Models with Prompt Strategies، استفاده از LLM را برای تجزیه و تشخیص آنلاین لاگ بدون آموزش درون‌دامنه بررسی کردند. هسته روش، ارائه دستور مرحله‌بندی‌شده، دانش وظیفه و درخواست توجیه تصمیم است تا مدل از معنا و زمینه رخداد استفاده کند.", citation="[1]")
    base.add_body(doc, "نسخه سال ۲۰۲۳ پایه خط پژوهشی LogPrompt را معرفی و چند وظیفه تحلیل لاگ را در یک چارچوب پرامپتی جمع می‌کند [1]. مقاله [6] نسخه توسعه‌یافته همین کار است؛ بنابراین نتایج آن‌ها مستقل از یکدیگر جمع نمی‌شوند. حضور جداگانه هر دو در پیشینه برای نشان‌دادن تحول نسخه و پوشش کامل فایل‌های موجود است.")

    add_labeled_body(doc, "مقاله ۲ ـ Exploring ChatGPT for Log-Based Anomaly Detection: ", "Qi و همکاران ChatGPT را برای تشخیص ناهنجاری روی BGL و Spirit بررسی کردند. پژوهش پنج محور را مطالعه می‌کند: تغییر پرامپت، اندازه پنجره، تزریق دانش انسانی، مقایسه با مدل‌های عمیق و تبیین‌پذیری. برای BGL اطلاعات اصلی شامل ۴٬۷۴۷٬۹۶۳ پیام و ۳۴۸٬۴۶۰ ناهنجاری گزارش شده است.", citation="[2]")
    base.add_body(doc, "به دلیل محدودیت نرخ API، مقاله دو هزار پیام متوالی از بخش آزمون را انتخاب و نسبت وجود ناهنجاری را به‌صورت دستی کنترل کرده است [2]. این محدودیت برای تفسیر نتیجه مهم است، زیرا آزمایش کل BGL نیست. پژوهش حاضر با مدل محلی و کش قالب برای اجرای گسترده‌تر طراحی می‌شود و علاوه بر F1، نرخ INVALID و زمان را ثبت می‌کند.")

    add_labeled_body(doc, "مقاله ۶ ـ نسخه توسعه‌یافته LogPrompt: ", "مقاله Prompt Engineering Towards Zero-Shot and Interpretable Log Analysis نسخه کامل‌تر LogPrompt است و راهبردهای پرامپت را روی ۹ مجموعه داده و چند وظیفه تجزیه و تشخیص ارزیابی می‌کند. اجزای پرامپت شامل تعریف وظیفه، دانش ضمنی یا صریح و زنجیره استدلال برای هدایت مدل به تصمیم و توضیح است.", citation="[6]")
    base.add_body(doc, "مقاله بهبود تا ۵۵٫۹ درصد نسبت به روش‌های آموزش‌دیده در برخی تنظیم‌ها و امتیاز ۴٫۴۲ از ۵ برای تفسیرپذیری در ارزیابی متخصصان را گزارش می‌کند [6]. تحلیل حذف مؤلفه در BGL نشان می‌دهد افزودن استدلال یا درخواست توجیه می‌تواند F1 سطح نشست و قالب را تغییر دهد. پژوهش حاضر برای کاهش خروجی آزاد، استدلال را به JSON دودویی محدود می‌کند.")

    add_labeled_body(doc, "مقاله ۳ ـ Hybrid Prompting: ", "Park، Choi و Lee سه نوع شواهد را در یک پرامپت ترکیب کردند: وجود رخداد دیده‌نشده، آمار و شباهت توالی و نزدیک‌ترین نمونه عادی. برای تعبیه از Qwen3-Embedding-8B و برای طبقه‌بندی از GPT-4o-mini استفاده شده است. HDFS، BGL و Thunderbird با پروتکل‌های توالی ارزیابی می‌شوند.", citation="[3]")
    base.add_body(doc, "روش در BGL با پنجره یک‌دقیقه‌ای و نمونه متوازن، Precision برابر ۶۳٫۶۵، Recall برابر ۹۹٫۶۰ و F1 برابر ۷۷٫۸۱ درصد گزارش می‌کند و میانگین بهبود F1 روی سه مجموعه ۹٫۹۳ واحد درصد است [3]. Hybrid Prompting ترکیب اطلاعات در متن است؛ Hybrid پایان‌نامه یک آبشار guard و LLM است و سطح تصمیم آن خط است.")

    base.add_heading(doc, "۲-۳-۵ بازیابی، همکاری مدل‌ها و کنترل هزینه", 3)
    add_labeled_body(doc, "مقاله ۱۲ ـ RAGLog: ", "Pan، Wong و Yuan پایگاه برداری را از نمونه‌های عادی تشکیل دادند و برای هر ورودی، نمونه مرتبط را بازیابی و همراه پیام به LLM ارائه کردند. نمونه‌های پایگاه با خوشه‌بندی K-means از BGL و Thunderbird انتخاب می‌شوند و مدل بدون دریافت نمونه ناهنجار، براساس شباهت و تحلیل معنایی تصمیم می‌گیرد.", citation="[12]")
    base.add_body(doc, "RAGLog در تنظیم گزارش‌شده Precision برابر ۰٫۹۱، Recall برابر ۰٫۸۸ و F1 برابر ۰٫۸۹ را در مقایسه با LogPrompt ارائه می‌کند [12]. مقاله مصرف منابع و تأخیر تحلیل خط‌به‌خط را محدودیت می‌داند. پایگاه برداری RAGLog نمونه را برای زمینه انتخاب می‌کند، درحالی‌که کش پایان‌نامه تصمیم معتبر قالب را بازاستفاده می‌کند.")

    add_labeled_body(doc, "مقاله ۱۳ ـ AdaptiveLog: ", "Ma و همکاران همکاری مدل زبانی کوچک و بزرگ را برای چند وظیفه تحلیل لاگ پیشنهاد کردند. مدل کوچک ابتدا نمونه را پردازش می‌کند؛ معیار عدم‌قطعیت تعیین می‌کند کدام نمونه به LLM ارجاع شود؛ و موارد دشوار مشابه از مخزن خطا بازیابی و در پرامپت قرار می‌گیرند. بازخورد LLM نیز برای بهبود تدریجی مدل کوچک استفاده می‌شود.", citation="[13]")
    base.add_body(doc, "AdaptiveLog کاهش هزینه فراخوانی LLM تا ۷۳ درصد را گزارش می‌کند [13]. این روش برای کنترل هزینه به یک مدل کوچک آموزش‌پذیر و معیار عدم‌قطعیت وابسته است. Hybrid پایان‌نامه به‌جای مدل کوچک، قواعد قطعی محدود را دروازه قرار می‌دهد و Prompt-only همان دروازه را حذف می‌کند؛ در نتیجه مقایسه بدون آموزش مدل جانبی انجام می‌شود.")

    add_labeled_body(doc, "مقاله ۱۰ ـ FlexLog: ", "Hadadi و همکاران FlexLog را برای تشخیص داده‌کارآمد روی لاگ‌های ناپایدار طراحی کردند. خروجی درخت تصمیم، KNN و شبکه پیش‌خور با Mistral، بازیابی نمونه و کش ترکیب می‌شود. مدل‌های کلاسیک موارد آشنا را پوشش می‌دهند و LLM برای نمونه‌های دشوار یا نیازمند معنا به‌کار می‌رود.", citation="[10]")
    base.add_body(doc, "آزمایش روی ADFA-U، LOGEVOL-U، SynHDFS-U و SYNEVOL-U انجام شده است. مقاله حداقل ۱٫۲ واحد درصد بهبود F1 با ۶۲٫۸۷ واحد درصد داده برچسب‌خورده کمتر، در برخی تنظیم‌ها تا ۱۳ واحد درصد بهبود و زمان استنتاج کمتر از یک ثانیه برای هر توالی گزارش می‌کند [10]. FlexLog از نظر کش و آبشار تصمیم نزدیک است، اما داده، واحد تحلیل و ترکیب چند طبقه‌بند آن با پایان‌نامه تفاوت دارد.")

    base.add_heading(doc, "۲-۳-۶ مطالعات تجزیه و تولید قالب لاگ", 3)
    add_labeled_body(doc, "مقاله ۲۴ ـ LogPPT: ", "Le و Zhang برای تجزیه لاگ، پرامپت‌تیونینگ few-shot را روی RoBERTa به‌کار گرفتند. الگوریتم نمونه‌گیری تصادفی تطبیقی مجموعه‌ای کوچک و متنوع از پیام‌ها را انتخاب می‌کند و مدل یاد می‌گیرد توکن‌های پارامتر را با یک برچسب مجازی تشخیص دهد. روش به عبارت منظم دستی وابسته نیست و تنظیمات یکسان را در دامنه‌های مختلف حفظ می‌کند.", citation="[24]")
    base.add_body(doc, "LogPPT روی ۱۶ مجموعه عمومی و با ۳۲ نمونه برچسب‌خورده ارزیابی شده و میانگین Group Accuracy و Parsing Accuracy بیش از ۰٫۹ گزارش می‌کند [24]. هدف آن تشخیص ناهنجاری نیست، ولی تعریف قالب و پارامتر مبنای نرمال‌سازی و کش قالب در پژوهش حاضر است.")

    add_labeled_body(doc, "مقاله ۲۳ ـ LogParser-LLM: ", "Zhong و همکاران معناشناسی LLM را با یک درخت پیشوند برای تجزیه برخط ترکیب کردند. پیام‌ها ابتدا با ساختار موجود تطبیق داده می‌شوند و فقط الگوهای جدید یا مبهم به LLM می‌روند. مقاله برای کنترل دانه‌بندی parser یک معیار و امکان بازخورد انسانی نیز پیشنهاد می‌کند.", citation="[23]")
    base.add_body(doc, "در LogPub با میانگین ۳٫۶ میلیون لاگ در ۱۴ مجموعه، LogParser-LLM به‌طور متوسط ۲۷۲٫۵ فراخوانی LLM، F1 گروه‌بندی ۹۰٫۶ درصد و Parsing Accuracy برابر ۸۱٫۱ درصد گزارش می‌کند [23]. این روش نشان می‌دهد تجمیع سطح قالب می‌تواند تعداد فراخوانی را کاهش دهد، اما خروجی آن قالب است و برچسب ناهنجاری تولید نمی‌کند.")

    base.add_heading(doc, "۲-۳-۷ مرورها، معیار ارزیابی، مدل پایه و استقرار واقعی", 3)
    add_labeled_body(doc, "مقاله ۱۴ ـ مرور نظام‌مند تشخیص ناهنجاری لاگ در عصر LLM: ", "De la Cruz Cabello، Prince Sales و Machado با روش مرور نظام‌مند، ۳۳ مقاله حوزه AIOps و تشخیص ناهنجاری لاگ را تحلیل کردند. مطالعه مراحل آماده‌سازی داده، تجزیه، استخراج ویژگی، مدل تشخیص، مجموعه‌های معیار و شیوه ارزیابی را طبقه‌بندی و روند حرکت از مدل‌های عمیق به LLM را جمع‌بندی می‌کند.", citation="[14]")
    base.add_body(doc, "این مقاله یک روش آزمایشی جدید روی BGL ارائه نمی‌کند و نقش آن ایجاد چارچوب دسته‌بندی و استخراج مسائل باز مانند هزینه، تفسیرپذیری، تعمیم و محرمانگی است [14]. ساختار دسته‌بندی فصل حاضر از محورهای این مرور استفاده می‌کند، اما جدول ۲-۱ به مجموعه ۲۷ فایل محلی محدود است.")

    add_labeled_body(doc, "مقاله ۲۰ ـ پیاده‌سازی واقعی AIOps: ", "De la Cruz Cabello و همکاران چارچوب خودنظارتی مبتنی بر LogBERT را روی Linux syslog عادی آموزش و در محیط دارای محدودیت محرمانگی به‌صورت محلی مستقر کردند. اثر حداقل تعداد توکن، اندازه و هم‌پوشانی پنجره و نرخ ماسک بر تشخیص و تأخیر بررسی شده است.", citation="[20]")
    base.add_body(doc, "پنجره ۱۵ ثانیه‌ای با هم‌پوشانی ۱۰ ثانیه بهترین موازنه گزارش‌شده میان اثربخشی و تأخیر را ایجاد کرد و ارزیابی متخصصان کاربرد عملی روش را تأیید نمود [20]. مقاله اهمیت استقرار محلی و اندازه‌گیری تأخیر را پشتیبانی می‌کند، اما مدل آن LogBERT آموزش‌دیده و داده آن syslog واقعی است، نه Qwen بدون تنظیم روی BGL.")

    add_labeled_body(doc, "مقاله ۲۵ ـ OpsEval: ", "Liu و همکاران یک مجموعه معیار برای ارزیابی توان LLM در عملیات فناوری اطلاعات ارائه کردند. OpsEval شامل ۷٬۳۳۴ سؤال چندگزینه‌ای و ۱٬۷۳۶ سؤال پاسخ‌آزاد در چند زیرحوزه است و ۲۴ مدل را تحت self-consistency، chain-of-thought و in-context learning مقایسه می‌کند.", citation="[25]")
    base.add_body(doc, "معیار FAE-Score پاسخ را از نظر روانی، صحت و شواهد می‌سنجد و هم‌بستگی حدود ۰٫۹۱۸۵ با ارزیابی متخصصان گزارش شده است [25]. OpsEval آشکارساز لاگ نیست، اما حساسیت مدل‌های عملیات به پرامپت و ضرورت تعریف معیار متناسب با خروجی را نشان می‌دهد. در پایان‌نامه، چون خروجی دودویی است، معیارهای ماتریس اغتشاش و INVALID جای معیار متنی را می‌گیرند.")

    add_labeled_body(doc, "مقاله ۲۶ ـ YuLan: ", "Zhu و همکاران گزارش فنی توسعه YuLan، یک مدل متن‌باز ۱۲ میلیارد پارامتری، را ارائه کردند. مدل با حدود ۱٫۷ تریلیون توکن چندزبانه پیش‌آموزی شده و پس از آن تنظیم دستوری و هم‌ترازی انسانی انجام گرفته است. مقاله برنامه‌درسی آسان‌به‌دشوار و جزئیات معماری، tokenizer و داده را تشریح می‌کند.", citation="[26]")
    base.add_body(doc, "YuLan روی ۲۲ معیار عمومی ارزیابی شده و مقاله‌ای درباره تشخیص ناهنجاری لاگ نیست [26]. حضور آن در فصل دوم برای تعریف مدل متن‌باز، مراحل پیش‌آموزی تا دستورپذیری و تفاوت مدل پایه با مدل Instruct است. انتخاب عملی پایان‌نامه Qwen2.5:7B-Instruct است و YuLan در آزمایش مقایسه‌ای استفاده نمی‌شود.")

    add_labeled_body(doc, "مقاله ۲۷ ـ مرور LLM برای Anomaly و OOD: ", "Xu و Ding آثار تشخیص ناهنجاری و داده خارج از توزیع با LLM را در حوزه‌های مختلف مرور و براساس نقش مدل به دو گروه LLM برای تشخیص و LLM برای تولید تقسیم کردند. مطالعه تفاوت تغییر هم‌توزیعی و تغییر معنایی، مجموعه‌های داده و مسیرهای آینده را توضیح می‌دهد.", citation="[27]")
    base.add_body(doc, "دامنه مقاله فراتر از لاگ و شامل متن، سری زمانی و سایر انواع داده است [27]. در این فصل از آن برای تعریف نقش مدل، تفکیک تشخیص از تولید و قرار دادن مطالعات تبیین یا افزایش داده در طبقه مناسب استفاده می‌شود؛ ارزیابی مستقیمی از Qwen یا BGL در آن وجود ندارد.")

    base.add_heading(doc, "۲-۳-۸ جمع‌بندی تحلیلی مسیر پژوهش‌ها", 3)
    base.add_body(doc, "مرحله نخست تحول ادبیات با مدل‌سازی توالی شکل گرفته است. DeepLog رخداد بعدی را پیش‌بینی می‌کند و LogBERT زمینه دوطرفه و وظیفه خودنظارتی را به توالی می‌افزاید [19، 21]. BERT-Log مسیر دیگری را دنبال می‌کند و بازنمایی BERT را با طبقه‌بند نظارت‌شده ترکیب می‌نماید [18]. این سه مطالعه مبنای تفاوت میان یادگیری الگوی عادی و طبقه‌بندی برچسب‌محور را مشخص می‌کنند.")
    base.add_body(doc, "مرحله دوم بر کاهش وابستگی به برچسب ناهنجار تمرکز دارد. LogFiT و ADALog از وظیفه MLM روی داده عادی استفاده می‌کنند [8، 22]. تفاوت آن‌ها در واحد تحلیل و parser است: LogFiT الگوی توکن در توالی را می‌سنجد، درحالی‌که ADALog پیام خام و مستقل را با آستانه تطبیقی ارزیابی می‌کند. این تفاوت نشان می‌دهد حذف برچسب به‌تنهایی واحد تصمیم را تعیین نمی‌کند.")
    base.add_body(doc, "مرحله سوم ورود LLM به‌عنوان مدل آموزش‌پذیر است. LogGPT مبتنی بر GPT، LogLLM، LLM-LADE و روش‌های PEFT از پیش‌آموزی عمومی آغاز می‌کنند، اما برای دامنه لاگ وزن‌ها یا نگاشت‌های مدل را تغییر می‌دهند [4، 5، 7، 9]. این خانواده با روش‌های prompt-only تفاوت بنیادی دارد، زیرا هزینه آموزش و داده انطباق بخشی از روش است.")
    base.add_body(doc, "مرحله چهارم استفاده از توان دستورپذیری بدون تغییر وزن است. دو نسخه LogPrompt و مطالعه ChatGPT-LogGPT اثر دستور، دانش دامنه و استدلال را بررسی می‌کنند [1، 2، 6]. Hybrid Prompting همین مسیر را با شواهد سطح توالی و نمونه بازیابی‌شده توسعه می‌دهد [3]. در این خانواده، متن پرامپت و روش انتخاب زمینه بخشی از مدل عملیاتی محسوب می‌شود.")
    base.add_body(doc, "مرحله پنجم به کنترل هزینه و مقیاس اختصاص دارد. RAGLog از بازیابی نمونه عادی، AdaptiveLog از واگذاری مبتنی بر عدم‌قطعیت و FlexLog از ترکیب مدل‌های کلاسیک، RAG و کش استفاده می‌کند [10، 12، 13]. LogParser-LLM نیز در وظیفه تجزیه نشان می‌دهد ساختار پیشوند می‌تواند فراخوانی را در مقیاس میلیون‌ها پیام محدود کند [23].")
    base.add_body(doc, "مسیر دیگری از ادبیات بر تفسیرپذیری متمرکز است. LogPrompt توضیح را در پاسخ مستقیم مدل قرار می‌دهد [1، 6]؛ LLM-LADE توضیح را همراه تشخیص آموزش می‌دهد [7]؛ و LogLAA آشکارساز عمیق و تولید توضیح را در دو جزء جدا ترکیب می‌کند [17]. این سه الگو نشان می‌دهند تفسیرپذیری می‌تواند خروجی زبانی، هدف آموزشی یا جزء پس‌پردازش باشد.")
    base.add_body(doc, "مطالعات انتقال و ناپایداری، محدودیت ارزیابی روی یک توزیع ثابت را مطرح می‌کنند. پژوهش GPT روی LOGEVOL تغییر نسخه را مستقیماً آزمایش می‌کند [11]؛ LogSynergy بازنمایی یکپارچه میان سامانه‌ها می‌سازد [15]؛ و FlexLog مجموعه‌های ناپایدار واقعی و مصنوعی را بررسی می‌کند [10]. پایان‌نامه حاضر این مسئله را به‌صورت تجربی پوشش نمی‌دهد و دامنه آن BGL ثابت است.")
    base.add_body(doc, "پژوهش‌های تجزیه نشان می‌دهند آماده‌سازی ورودی یک مسئله مستقل است. LogPPT با few-shot و LogParser-LLM با LLM و درخت پیشوند، کیفیت قالب را به‌عنوان خروجی اصلی می‌سنجند [23، 24]. بنابراین هر بهبود آشکارساز که پس از تغییر parser رخ دهد باید از اثر خود parser تفکیک شود. پایان‌نامه نرمال‌سازی را در هر دو روش ثابت نگه می‌دارد.")
    base.add_body(doc, "مطالعه کاربرد واقعی AIOps فاصله میان معیار عمومی و استقرار را نشان می‌دهد؛ پارامتر پنجره و تأخیر به اندازه دقت برای کار عملی اهمیت دارند [20]. OpsEval نیز نشان می‌دهد ارزیابی LLM در عملیات به معیار و پرامپت تخصصی نیاز دارد [25]. این دو منبع مبنای گزارش زمان، نسخه مدل و قرارداد خروجی در کنار F1 هستند.")
    base.add_body(doc, "دو مقاله مروری نقش کنترل دامنه را دارند. مرور نظام‌مند لاگ، مراحل خط لوله و شکاف‌های AIOps را استخراج می‌کند [14] و مرور Anomaly/OOD نقش LLM را به تشخیص و تولید تقسیم می‌نماید [27]. جدول فصل از اولی برای محورهای لاگ و از دومی برای نقش مدل استفاده می‌کند؛ هیچ‌یک به‌عنوان نتیجه آزمایش BGL شمرده نمی‌شود.")
    base.add_body(doc, "YuLan نیز در گروه نتیجه تشخیص قرار نمی‌گیرد، اما مراحل ساخت مدل پایه، تنظیم دستوری و هم‌ترازی را مستند می‌کند [26]. این تفکیک برای پایان‌نامه لازم است، زیرا Qwen2.5:7B-Instruct محصول چنین مراحل عمومی است، ولی وزن آن در پروژه تغییر نمی‌کند و فقط در زمان استنتاج به‌کار می‌رود [28].")
    base.add_body(doc, "برآیند ۲۷ مقاله نشان می‌دهد پنج تصمیم طراحی باید صریح باشند: واحد تحلیل، نوع انطباق مدل، روش آماده‌سازی، سازوکار کنترل هزینه و محل استقرار. دو روش Hybrid و Prompt-only در پایان‌نامه فقط یکی از این تصمیم‌ها—محل اعمال دانش قاعده—را تغییر می‌دهند و سایر عوامل برای مقایسه ثابت می‌مانند.")

    base.add_heading(doc, "۲-۴ دسته‌بندی و تحلیل مقایسه‌ای", 2)
    base.add_body(doc, "شکل ۲-۱ تمام ۲۷ مقاله را در شش مسیر روش‌شناختی قرار می‌دهد و سپس نشان می‌دهد کدام مؤلفه‌ها در طراحی پژوهش حاضر به هم می‌رسند. شماره‌های شکل با شماره فایل‌های پوشه و ارجاع‌های فصل یکسان‌اند. قرارگرفتن یک مقاله در یک دسته به معنای نبود مؤلفه‌های دسته دیگر نیست؛ برای نمونه FlexLog هم مدل کلاسیک، LLM، RAG و کش دارد [10].")
